CREATE TABLE [sales].[InvoiceSeries]([InvoiceSeriesId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_InvoiceSeries_Id] DEFAULT NEWSEQUENTIALID(),[SeriesCode] NVARCHAR(20) NOT NULL,[Prefix] NVARCHAR(20) NOT NULL,[FinancialYear] NVARCHAR(9) NOT NULL,[NextNumber] BIGINT NOT NULL CONSTRAINT [DF_InvoiceSeries_Next] DEFAULT 1,[NumberLength] TINYINT NOT NULL CONSTRAINT [DF_InvoiceSeries_Length] DEFAULT 6,[IsDefault] BIT NOT NULL CONSTRAINT [DF_InvoiceSeries_Default] DEFAULT 0,[IsActive] BIT NOT NULL CONSTRAINT [DF_InvoiceSeries_Active] DEFAULT 1,[RowVersion] ROWVERSION NOT NULL,CONSTRAINT [PK_InvoiceSeries] PRIMARY KEY([InvoiceSeriesId]),CONSTRAINT [UQ_InvoiceSeries_CodeYear] UNIQUE([SeriesCode],[FinancialYear]));
